#include <stdio.h>

int main() {
    int n;
    double max = -1;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double calificacion;
        scanf("%lf", &calificacion);
        if (calificacion >= 0) {
            if (max < calificacion) {
                max = calificacion;
            }
        }
    }
    printf("%.1f\n", max);
    return 0;
}

