#include <stdio.h>

int main() {
    int n;
    int aprobar = 0;
    int reprobado = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double calificacion;
        scanf("%lf", &calificacion);
        /* HUECO 1: incrementar aprobar si calificacion >= 6 */
        /* HUECO 2: incrementar reprobado si calificacion < 6 */
    }
    printf("%d %d\n", aprobar, reprobado);
    return 0;
}

contenido.solucion:
#include <stdio.h>

int main() {
    int n;
    int aprobar = 0;
    int reprobado = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double calificacion;
        scanf("%lf", &calificacion);
        if (calificacion >= 6) {
            aprobar++;
        } else {
            reprobado++;
        }
    }
    printf("%d %d\n", aprobar, reprobado);
    return 0;
}
